        Root cause:
        The bug was caused by incorrect pointer arithmetic when initializing the stack pointer. The original code added `stack_size` to `stack_start` without using parentheses, which resulted in the stack pointer being set to the end of the stack instead of the beginning. This miscalculation led to potential stack corruption and incorrect behavior during task execution.

        Commit message:
        fix bug introduced by
 7cef6c46552a988c1c710a0a2404316a27ef1d43 stack_start used to be stack_start +
 stack_size, so re-setting stk to stack_start would set the pointer to the
 *end* of the stack instead of the beginning.  

        Patch:
         //----------------------------------------------------------------------------
 char *thread_stack_init(void *task_func, void *stack_start, int stack_size)
 {
     unsigned short * stk;
-    stk = (unsigned short *) stack_start + stack_size;
+    stk = (unsigned short *) (stack_start + stack_size);

     *stk = (unsigned short) sched_task_exit;
     --stk;

     *stk = (unsigned short) task_func;
     --stk;

     /* initial value for SR */
 //    unsigned int sr;
 //    __asm__("mov.w r2,%0" : "=r" (sr));

     *stk = GIE;
     --stk;

     /* Space for registers. */
     for (unsigned int i = 15; i > 4; i--) {
         *stk = i;
         --stk;
     }
     //stk -= 11;

     return (char*) stk;
 }



